    const horaAtual = Number(item.json.Hour || 0);       // pega a hora do input
    const diaSemana = Number(item.json["Day of week num"] ?? null) 
        || new Date(item.json.timestamp).getDay();       // se tiver dia como número, usa, senão converte do timestamp

    // Permite apenas se não for domingo (0) e hora entre 9h e 20h
    return diaSemana !== 0 && horaAtual >= 8 && horaAtual <= 22});

